#!/usr/bin/env python3
"""
Round 203o (culprits), 14 October 2026. Needs round 202o.

Moon and Mars globe; clearer rows; marks clickable on Mars.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 203o (14 October)\n\nNeeds round 202o (guards on its heading). Tiles patch round203o_tiles.py\nbeside it (bodies.py: globe pictures, the Moon list\'s key and totals). No\napp.js?v= bump.\n\n- Moon and Mars (asked 14 October): a Flat map / Globe choice. The globe is\n  globe.gl 2.46.2 (MIT, from unpkg), wrapped in bodies/<body>_globe.jpg,\n  which bodies.py stitches from the same Trek tiles at zoom 3 (4096 x 2048);\n  until it is built the globe shows the marks on a plain sphere and says so.\n  On it: the ticked rows\' marks (a click opens the same box), the rover\n  routes, and the 90 largest features\' names.\n- Mars "froze" (no mark could be clicked): the rover routes were drawn on a\n  second canvas over the marks\' canvas, which took every click; they now\n  share one canvas (renderer: glow).\n- Longitudes are brought into -180 to 180 (Wikipedia gives Mars 2 at\n  313 W, drawn off the map before).\n- Names: biggest first, none over another (the rest come as you zoom in).\n- Rows renamed to say how they differ: LROC "hardware spotted in orbital\n  photos" (exact places, no masses) against Wikipedia "every mission\'s\n  spacecraft, by weight" (masses, approximate places, small items out);\n  the map\'s eight rows likewise, with the difference in their notes.\n- Rover boxes are titled with the rover and sol.\n- Tiles: bodies.py keeps the Moon list\'s colour key and its total-mass line\n  in the file\'s "keys" and "totals" instead of taking them as rows and\n  column names.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round203o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 202o" not in h.read_text(encoding="utf-8"):
        sys.exit("round203o: round 202o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round203o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round203o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round203o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
